import{c as a,Q as t,j as i,m as n}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Weak-to-Strong Generalization: Eliciting Strong Capabilities With Weak Supervision","description":"","frontmatter":{"url":"https://arxiv.org/abs/2312.09390","title":"Weak-to-Strong Generalization: Eliciting Strong Capabilities With Weak Supervision","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2312.0939,"authors":["Collin Burns","Pavel Izmailov","Jan Hendrik Kirchner","Bowen Baker","Leo Gao","Leopold Aschenbrenner","Yining Chen","Adrien Ecoffet","Manas Joglekar","Jan Leike","Ilya Sutskever","Jeff Wu (OpenAI)"],"pdf_path":"pdfs/2312.09390.pdf","published_date":"2023-01-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2023-12-14-weak-to-strong-generalization-2312-09390.md","filePath":"research/papers/2023-12-14-weak-to-strong-generalization-2312-09390.md","lastUpdated":1785909234000}'),r={name:"research/papers/2023-12-14-weak-to-strong-generalization-2312-09390.md"};function s(o,e,l,u,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="weak-to-strong-generalization-eliciting-strong-capabilities-with-weak-supervision" tabindex="-1">Weak-to-Strong Generalization: Eliciting Strong Capabilities With Weak Supervision <a class="header-anchor" href="#weak-to-strong-generalization-eliciting-strong-capabilities-with-weak-supervision" aria-label="Permalink to &quot;Weak-to-Strong Generalization: Eliciting Strong Capabilities With Weak Supervision&quot;">​</a></h1><p><strong>Authors:</strong> Collin Burns, Pavel Izmailov, Jan Hendrik Kirchner, Bowen Baker, Leo Gao, Leopold Aschenbrenner, Yining Chen, Adrien Ecoffet, Manas Joglekar, Jan Leike, Ilya Sutskever, Jeff Wu (OpenAI) <strong>Year:</strong> 2023 (submitted December 14, 2023) <strong>Venue:</strong> Preprint (OpenAI Technical Report); associated with OpenAI Superalignment initiative <strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2312.09390" target="_blank" rel="noreferrer">https://arxiv.org/abs/2312.09390</a></p><hr><h2 id="full-abstract" tabindex="-1">Full Abstract <a class="header-anchor" href="#full-abstract" aria-label="Permalink to &quot;Full Abstract&quot;">​</a></h2><p>A core challenge in aligning future superhuman AI models is that humans may not be able to reliably evaluate the AI&#39;s capabilities. This paper investigates whether weaker models can supervise stronger models—termed &quot;weak-to-strong generalization&quot;—as a tractable analogy for the superalignment problem. Experiments across GPT-4 family models on NLP benchmarks, chess, and reward modeling find that strong pretrained models consistently outperform their weak supervisors when finetuned on weak-model-generated labels. Using auxiliary confidence loss with GPT-2-level supervision on GPT-4 recovered close to GPT-3.5-level performance on NLP tasks. The results suggest current alignment techniques like RLHF may be fundamentally insufficient for superhuman models.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>Superalignment framed as empirical research question:</strong> Recast the abstract problem of aligning superhuman AI as a concrete, testable question—&quot;can a weak model supervise a strong one?&quot;—making it tractable for near-term experimental investigation.</li><li><strong>Weak-to-strong generalization demonstrated:</strong> Strong pretrained models consistently generalize beyond their weak supervisors across NLP benchmarks, chess puzzles, and reward modeling, showing that pretrained knowledge enables models to &quot;fill in&quot; correct behavior beyond what weak labels specify.</li><li><strong>Auxiliary confidence loss proposed:</strong> A practical training technique where the strong model is penalized for low-confidence predictions on its own unlabeled data, recovering substantial performance gap under weak supervision (GPT-2 → GPT-4 supervision gap partially closed).</li><li><strong>RLHF insufficiency warning:</strong> Provides the first systematic empirical evidence that standard RLHF-style finetuning on weak-supervisor labels may be fundamentally inadequate for aligning models substantially more capable than their overseers.</li><li><strong>Research program and funding launched:</strong> Released open research directions and announced $10M in external grants to accelerate superalignment research, positioning this as a community-scale research agenda rather than a closed project.</li><li><strong>Benchmark across modalities:</strong> Chess puzzle performance and reward modeling experiments extend findings beyond NLP, suggesting the phenomenon is domain-general rather than an artifact of language task structure.</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p><strong>Experimental Setup — Weak-to-Strong Analogy:</strong> The paper operationalizes the superalignment challenge using the GPT-4 model family as a controlled testbed. A &quot;weak supervisor&quot; (e.g., GPT-2 or a small GPT-4 variant) generates labels for a set of tasks. A &quot;strong student&quot; (e.g., a larger GPT-4 variant) is then finetuned on these weak labels. The key question: does the strong student&#39;s performance exceed what the weak labels alone would predict, and can it approach the performance ceiling of the strong model trained with ground-truth labels? This mirrors the anticipated future scenario where humans (weak supervisors) must align superhuman AI (strong students).</p><p><strong>Tasks and Evaluation:</strong> Three task categories are used: (1) NLP benchmarks (classification and generation tasks where accuracy against ground truth is measurable), (2) chess puzzle solving (a domain with clear correct answers requiring reasoning beyond what a weak supervisor can evaluate), and (3) reward modeling (training a reward model on weak-supervisor preference labels, then evaluating its alignment with ground-truth human preferences). Results across all three show consistent weak-to-strong generalization effects, though the magnitude varies by domain and capability gap size.</p><p><strong>Auxiliary Confidence Loss:</strong> To improve upon naive finetuning on weak labels, the authors propose an auxiliary loss term that encourages the strong model to maintain high confidence on its own unlabeled predictions. This functions as a form of self-consistency regularization: the strong model&#39;s internal knowledge, encoded in its pretrained weights, is leveraged as an additional supervision signal beyond the weak labels. Empirically, this recovers a meaningful fraction of the capability gap—e.g., GPT-4 finetuned with GPT-2-level supervision plus confidence loss approaches GPT-3.5-level NLP performance.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><ul><li>Strong students consistently outperform weak supervisors after finetuning on weak labels, confirming weak-to-strong generalization as a robust phenomenon across tasks and model scales.</li><li>Without auxiliary loss, a significant &quot;imitation gap&quot; persists: the strong student underperforms what it would achieve under ground-truth supervision, suggesting naive RLHF will leave capability unused in superhuman regimes.</li><li>Auxiliary confidence loss reduces the imitation gap substantially on NLP tasks; the effect is smaller on chess and reward modeling, suggesting domain-specific techniques may be needed.</li><li>The magnitude of weak-to-strong generalization scales with the pretrained capability of the strong model—more capable base models generalize more effectively from weak supervision.</li><li>Reward modeling experiments show that even when the reward model is trained on weak-supervisor labels, the resulting policy can surpass the weak supervisor&#39;s own performance ceiling, but with noticeable alignment degradation compared to ground-truth-trained reward models.</li><li>Chess experiments reveal that weak supervisors (unable to solve hard puzzles) can still provide labels that enable strong students to solve puzzles the supervisor could not evaluate—direct evidence of supervision beyond evaluator competence.</li></ul><hr><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>The GPT-4 family provides a controlled but narrow testbed; results may not generalize to truly superhuman capability gaps (e.g., humans supervising a model 100× more capable).</li><li>Auxiliary confidence loss is a heuristic; its theoretical grounding and failure modes under distribution shift are not fully characterized.</li><li>Chess and reward modeling show weaker weak-to-strong generalization than NLP, suggesting the effect is task-dependent and may not universally rescue alignment under weak supervision.</li><li>The paper does not address adversarial weak supervisors or cases where weak labels are systematically biased (e.g., human annotators with consistent ideological blind spots).</li><li>Scalable oversight techniques (debate, amplification) are not compared head-to-head with weak-to-strong generalization; the relationship between these paradigms is left for future work.</li><li>Open questions: How does the capability gap threshold affect generalization? What training data mixtures maximize weak-to-strong transfer? Can this framework be extended to multi-step reasoning and agency?</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>This paper reframes the long-term AI safety problem as something researchable today with available models. For practitioners, the near-term implication is stark: if your finetuning supervisor (human annotator or AI labeler) cannot reliably evaluate the model&#39;s outputs in a domain, standard RLHF may not produce the alignment you expect—the model may silently revert to pretrained biases or learn to satisfy the evaluator&#39;s limited judgment rather than genuinely improving. The auxiliary confidence loss technique offers a practical mitigation: leverage the model&#39;s own pretrained knowledge as a self-consistency check during alignment fine-tuning. For teams building reward models or preference-based pipelines, this work argues for investing in better evaluation infrastructure (e.g., debate, amplification, automated test suites) rather than assuming human raters can reliably distinguish quality as model capability scales. The research program it launched—superalignment—has become a significant research direction across the field.</p>',22)])])}const p=a(r,[["render",s]]);export{g as __pageData,p as default};
